   197	def evaluate_expression(expression):
   198	    """
   199	    Evaluate an arithmetic expression and return the result.
   200	    Returns (result, None) on success or (None, error_message) on failure.
   201	    """
   202	    if not expression or not expression.strip():
   203	        return None, "Empty expression"
   204	    
   205	    try:
   206	        parser = ArithmeticParser(expression)
   207	        result = parser.parse()
   208	        
   209	        # Round to 6 decimal places using ROUND_HALF_UP
   210	        result = result.quantize(Decimal('0.000001'), rounding=ROUND_HALF_UP)
   211	        
   212	        # Normalize to remove trailing zeros
   213	        result = result.normalize()
   214	        
   215	        # Convert to float for JSON serialization
   216	        result_float = float(result)
   217	        
   218	        # If it's an integer, return as int
   219	        if result_float == int(result_float):
   220	            return int(result_float), None
   221	        
   222	        return result_float, None
   223	        
   224	    except (ValueError, InvalidOperation) as e:
   225	        return None, str(e)
   226	    except Exception as e:
